ALTER TABLE `sales` ADD COLUMN `paymentCondition` ENUM('CASH', 'INSTALLMENT') NOT NULL DEFAULT 'CASH';
CREATE TABLE `receivables` (`id` VARCHAR(191) NOT NULL, `description` VARCHAR(191) NOT NULL, `totalAmount` DECIMAL(10,2) NOT NULL, `status` ENUM('PENDING','PARTIALLY_PAID','PAID','CANCELED') NOT NULL DEFAULT 'PENDING', `companyId` VARCHAR(191) NOT NULL, `customerId` VARCHAR(191) NULL, `saleId` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `receivables_saleId_key` (`saleId`), INDEX `receivables_companyId_idx` (`companyId`), INDEX `receivables_customerId_idx` (`customerId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `payment_installments` (`id` VARCHAR(191) NOT NULL, `number` INTEGER NOT NULL, `amount` DECIMAL(10,2) NOT NULL, `paidAmount` DECIMAL(10,2) NOT NULL DEFAULT 0, `dueDate` DATETIME(3) NOT NULL, `status` ENUM('PENDING','PARTIALLY_PAID','PAID','CANCELED') NOT NULL DEFAULT 'PENDING', `receivableId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `payment_installments_dueDate_idx` (`dueDate`), UNIQUE INDEX `payment_installments_receivableId_number_key` (`receivableId`,`number`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `payment_receipts` (`id` VARCHAR(191) NOT NULL, `amount` DECIMAL(10,2) NOT NULL, `paymentMethod` ENUM('PIX','CASH','CARD') NOT NULL, `receivedAt` DATETIME(3) NOT NULL, `notes` TEXT NULL, `installmentId` VARCHAR(191) NOT NULL, `companyId` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `payment_receipts_companyId_idx` (`companyId`), INDEX `payment_receipts_installmentId_idx` (`installmentId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `receivables` ADD CONSTRAINT `receivables_companyId_fkey` FOREIGN KEY (`companyId`) REFERENCES `companies`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `receivables_customerId_fkey` FOREIGN KEY (`customerId`) REFERENCES `customers`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `receivables_saleId_fkey` FOREIGN KEY (`saleId`) REFERENCES `sales`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `payment_installments` ADD CONSTRAINT `payment_installments_receivableId_fkey` FOREIGN KEY (`receivableId`) REFERENCES `receivables`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `payment_receipts` ADD CONSTRAINT `payment_receipts_installmentId_fkey` FOREIGN KEY (`installmentId`) REFERENCES `payment_installments`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `payment_receipts_companyId_fkey` FOREIGN KEY (`companyId`) REFERENCES `companies`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `payment_receipts_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `financial_transactions` ADD COLUMN `paymentReceiptId` VARCHAR(191) NULL, ADD UNIQUE INDEX `financial_transactions_paymentReceiptId_key` (`paymentReceiptId`), ADD CONSTRAINT `financial_transactions_paymentReceiptId_fkey` FOREIGN KEY (`paymentReceiptId`) REFERENCES `payment_receipts`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
